import{_ as t,o as a,c as n,a3 as s}from"./chunks/framework.B5WAEDB7.js";const u=JSON.parse('{"title":"Syntax","description":"Dots, parentheses, quotation marks — the rules for ApptiveScript expressions.","frontmatter":{"title":"Syntax","description":"Dots, parentheses, quotation marks — the rules for ApptiveScript expressions."},"headers":[],"relativePath":"en/apptivescript/schreibweise.md","filePath":"en/apptivescript/schreibweise.md","lastUpdated":1787319236000}'),o={name:"en/apptivescript/schreibweise.md"};function i(r,e,d,l,c,p){return a(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="syntax" tabindex="-1">Syntax <a class="header-anchor" href="#syntax" aria-label="Permalink to &quot;Syntax&quot;">​</a></h1><p>ApptiveScript has few rules. This page lists all of them.</p><h2 id="value-dot-function" tabindex="-1">Value, dot, function <a class="header-anchor" href="#value-dot-function" aria-label="Permalink to &quot;Value, dot, function&quot;">​</a></h2><p>Every expression starts with a value. After that, functions follow, each separated by a dot:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fieldValue(&#39;price&#39;).multiplyBy(1.19)</span></span></code></pre></div><p>The result of a function is a value again — which means functions can be <strong>chained</strong>. It&#39;s read left to right:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fieldValue(&#39;lastName&#39;).concat(fieldValue(&#39;firstName&#39;), &#39;, &#39;).isNotEmpty()</span></span></code></pre></div><p>Which functions are allowed depends on the type of the value to the left of the dot. A text value can use <code>contains()</code>, a number can use <code>round()</code>. → <a href="/en/referenz/apptivescript-funktionen">Function reference</a></p><p>Spaces and line breaks between the parts are allowed. For longer chains, this is the more readable form:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fieldValue(&#39;quantity&#39;)</span></span>
<span class="line"><span>  .multiplyBy(fieldValue(&#39;unitPrice&#39;))</span></span>
<span class="line"><span>  .round(2)</span></span></code></pre></div><h2 id="functions-always-have-parentheses" tabindex="-1">Functions always have parentheses <a class="header-anchor" href="#functions-always-have-parentheses" aria-label="Permalink to &quot;Functions always have parentheses&quot;">​</a></h2><p>Even when they don&#39;t need an argument:</p><table tabindex="0"><thead><tr><th>Correct</th><th>Wrong</th></tr></thead><tbody><tr><td><code>today()</code></td><td><code>today</code></td></tr><tr><td><code>fieldValue(&#39;title&#39;).isEmpty()</code></td><td><code>fieldValue(&#39;title&#39;).isEmpty</code></td></tr></tbody></table><p>The exception is <strong>properties</strong>. They appear without parentheses because they don&#39;t calculate anything — they just name part of a value. In the function reference, they&#39;re listed with a leading dot:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>loggedInUser().email</span></span></code></pre></div><p><code>true</code> and <code>false</code> are also properties and appear without parentheses.</p><h2 id="text-numbers-booleans" tabindex="-1">Text, numbers, booleans <a class="header-anchor" href="#text-numbers-booleans" aria-label="Permalink to &quot;Text, numbers, booleans&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Kind</th><th>Syntax</th><th>Example</th></tr></thead><tbody><tr><td>Text</td><td><strong>single</strong> quotation marks</td><td><code>&#39;Other&#39;</code></td></tr><tr><td>Whole number</td><td>no separator</td><td><code>42</code>, <code>-7</code></td></tr><tr><td>Decimal number</td><td>with a <strong>dot</strong> as the decimal separator</td><td><code>1.19</code></td></tr><tr><td>Boolean</td><td>no parentheses, lowercase</td><td><code>true</code>, <code>false</code></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Three typos that break an expression</p><ul><li><strong>Double quotation marks</strong> (<code>&quot;Other&quot;</code>) aren&#39;t valid text. The editor reports an error.</li><li><strong>A comma as decimal separator</strong> (<code>1,19</code>) isn&#39;t read correctly. Always use <code>1.19</code>.</li><li><strong>Capitalization matters</strong>: <code>True</code> is not <code>true</code>, <code>IsEmpty()</code> is not <code>isEmpty()</code>. A misspelled name is treated as unknown — and an unknown name isn&#39;t an error, it&#39;s simply blank.</li></ul></div><div class="danger custom-block"><p class="custom-block-title">Apostrophes in text don&#39;t work</p><p>An apostrophe inside a text value can&#39;t be written — <code>&#39;Müller&#39;s shop&#39;</code> cuts the text off after <code>Müller</code>, <strong>without</strong> any error message appearing. Avoid apostrophes in comparison values, or compare against part of the text using <code>contains()</code>.</p></div><h2 id="doing-math" tabindex="-1">Doing math <a class="header-anchor" href="#doing-math" aria-label="Permalink to &quot;Doing math&quot;">​</a></h2><p>For numbers, both notations are available — operators and functions:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(fieldValue(&#39;net&#39;) + fieldValue(&#39;shipping&#39;)) * 1.19</span></span>
<span class="line"><span>fieldValue(&#39;net&#39;).plus(fieldValue(&#39;shipping&#39;)).multiplyBy(1.19)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Operator</th><th>Function</th></tr></thead><tbody><tr><td><code>+</code></td><td><code>plus()</code></td></tr><tr><td><code>-</code></td><td><code>minus()</code></td></tr><tr><td><code>*</code></td><td><code>multiplyBy()</code></td></tr><tr><td><code>/</code></td><td><code>divideBy()</code></td></tr></tbody></table><p>Parentheses group terms: <code>(2 + 3) * 4</code> gives 20.</p><div class="tip custom-block"><p class="custom-block-title">When in doubt, use the function notation</p><p>The editor inserts functions rather than operators when you click things together — and chains of functions can be extended without thinking about operator precedence. Operators are mainly convenient for short formulas.</p></div><h2 id="combining-conditions" tabindex="-1">Combining conditions <a class="header-anchor" href="#combining-conditions" aria-label="Permalink to &quot;Combining conditions&quot;">​</a></h2><p>There are no keywords for <em>and</em>, <em>or</em>, <em>not</em> — they&#39;re functions on a boolean value:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>formValues.get(&#39;age&#39;).greaterThan(17).logicalAnd(formValues.get(&#39;terms&#39;).isTrue())</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Meaning</th><th>Syntax</th></tr></thead><tbody><tr><td>and</td><td><code>condition.logicalAnd(otherCondition)</code></td></tr><tr><td>or</td><td><code>condition.logicalOr(otherCondition)</code></td></tr><tr><td>not</td><td><code>condition.isFalse()</code></td></tr><tr><td>if/else</td><td><code>condition.if(then, otherwise)</code></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Don&#39;t mix AND and OR</p><p>The interface can only display an expression as rows if it&#39;s connected entirely with AND <strong>or</strong> entirely with OR. If you mix them, the Flow dialog reports:</p><blockquote><p><em>This expression mixes AND/OR or can&#39;t be split into rows. Edit it as a single expression, or use rows with a shared operator (AND only or OR only).</em></p></blockquote><p>The expression keeps working — it just can no longer be edited via the rows.</p></div><h2 id="missing-values" tabindex="-1">Missing values <a class="header-anchor" href="#missing-values" aria-label="Permalink to &quot;Missing values&quot;">​</a></h2><p>An empty field doesn&#39;t produce an error, but an empty value. Two functions handle that:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fieldValue(&#39;nickname&#39;).ifUndefined(&#39;unknown&#39;)</span></span>
<span class="line"><span>fieldValue(&#39;orderNumber&#39;).isNotEmpty()</span></span></code></pre></div><p><code>ifUndefined()</code> is available on every type. It matters most anywhere further calculation happens — multiplying by an empty field doesn&#39;t produce a result, it produces nothing.</p><h2 id="what-doesn-t-exist" tabindex="-1">What doesn&#39;t exist <a class="header-anchor" href="#what-doesn-t-exist" aria-label="Permalink to &quot;What doesn&#39;t exist&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Comments</strong></td><td><code>// …</code> and <code>/* … */</code> are invalid</td></tr><tr><td><strong>Variables and intermediate steps</strong></td><td>an expression is a single line</td></tr><tr><td><strong>Multiple results</strong></td><td>an expression returns exactly one value</td></tr><tr><td><strong>German function names</strong></td><td>names are in English, even in the German interface</td></tr></tbody></table><h2 id="editor-error-messages" tabindex="-1">Editor error messages <a class="header-anchor" href="#editor-error-messages" aria-label="Permalink to &quot;Editor error messages&quot;">​</a></h2><p>The expression editor shows errors below the field, in English and with internal type names:</p><table tabindex="0"><thead><tr><th>Message</th><th>Meaning</th></tr></thead><tbody><tr><td><em>ASString class has no function named …</em></td><td>This function doesn&#39;t exist for this type — check the <a href="/en/referenz/apptivescript-funktionen">function reference</a></td></tr><tr><td><em>function needs 1 arguments</em></td><td>Too few or too many arguments in the parentheses</td></tr><tr><td><em>Unexpected token …</em></td><td>The expression is incomplete, e.g. a missing parenthesis or a trailing dot</td></tr><tr><td><em>No field with id …</em></td><td>The column being referenced no longer exists</td></tr></tbody></table><p>If an expression can&#39;t be parsed, the text you entered stays unchanged in the field instead of being converted into blocks. That&#39;s the fastest way to spot a typo.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/apptivescript/werte-referenzieren">Referencing values</a> — what an expression starts with</li><li><a href="/en/apptivescript/bedingungen">Building conditions</a> — comparisons, AND/OR, branches</li><li><a href="/en/apptivescript/editor">The expression editor</a> — token view, picker, sample result</li><li><a href="/en/referenz/apptivescript-funktionen">Function reference</a> — every function by type</li><li><a href="/en/apptivescript/was-ist-apptivescript">What is ApptiveScript</a></li></ul>`,43)])])}const m=t(o,[["render",i]]);export{u as __pageData,m as default};
